# Reviewed under AGENTS.md
import csv, json

users = []
with open('users.csv', newline='', encoding='utf-8') as f:
    for row in csv.DictReader(f):
        users.append((row['id'], row['name'], row['country']))

ids = {u[0] for u in users}
totals = {u[0]: 0.0 for u in users}

with open('orders.jsonl', encoding='utf-8') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        o = json.loads(line)
        if o.get('status') != 'paid':
            continue
        uid = o.get('user_id')
        if uid not in ids:
            continue
        totals[uid] += float(o.get('total', 0))

report = [
    {'user': name, 'country': country, 'paid_total': round(totals[uid], 2)}
    for uid, name, country in users
]
report.sort(key=lambda r: (-r['paid_total'], r['user']))

with open('report.json', 'w', encoding='utf-8') as f:
    json.dump(report, f, indent=2)
    f.write('\n')

print(json.dumps(report, indent=2))
